const Dashboard = () => {
  return (
    <div style={{ padding: 24, minHeight: "100vh", background: "#eef2ff" }}>
      <div style={{ maxWidth: 960, margin: "0 auto" }}>
        <h1>Doctor Dashboard</h1>
        <p>Welcome to the doctor panel. Use this app to manage schedule, patients, and appointments.</p>
      </div>
    </div>
  );
};

export default Dashboard;
